// stepsProvider lists the phones a test sets, as their driver would while
// they wait for a step, and opens none.
type stepsProvider struct {
	platform driver.Platform
	mu       sync.Mutex
	infos    []driver.Info
}

func (p *stepsProvider) Platform() driver.Platform { return p.platform }

func (p *stepsProvider) List(context.Context) ([]driver.Info, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	return slices.Clone(p.infos), nil
}

func (p *stepsProvider) Open(context.Context, string) (driver.Device, error) {
	return nil, driver.ErrOffline
}

// list lists infos from the next discovery on; none unplugs every phone.
func (p *stepsProvider) list(infos ...driver.Info) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.infos = infos
}

// newStepsApp is the client on the real gateway, with phones from ps.
func newStepsApp(t *testing.T, ps ...driver.Provider) *gwApp {
	t.Helper()
	g, err := gateway.New(gateway.Options{Providers: ps, Policy: policy.Default(), TrustNewAgents: true,
		DiscoverEvery: 20 * time.Millisecond, NoScreenshots: true})
	if err != nil {
		t.Fatal(err)
	}
	ga := &gwApp{w: &demogw.World{Gateway: g}}
	ga.app = newApp(g, Options{NoTray: true, Shortcut: "-"})
	testHooks(t, ga.app)
	ga.app.videoErr = errors.New("no video in tests")
	ga.app.postHook = func(fn func()) {
		ga.mu.Lock()
		ga.q = append(ga.q, fn)
		ga.mu.Unlock()
	}
	t.Cleanup(func() {
		ga.app.end()
		g.Close()
	})
	return ga
}

// TestPhonesThatNeedSetup: on the real gateway, phones their drivers list
// as waiting for a step (an Android phone to allow USB debugging, an
// iPhone to trust the computer, then Developer Mode) need setup; they are
// not offline. The sidebar, the tiles and the menu bar flyout say so, and
// each phone's page says the step in the person's words, as its checkup
// does, with See what's wrong and, for the iPhone, its steps in Add
// phone. Unplugged, they are offline and say no step. In English and
// Chinese.
func TestPhonesThatNeedSetup(t *testing.T) {
	droid, ios := &stepsProvider{platform: driver.Android}, &stepsProvider{platform: driver.IOS}
	pixel := driver.Info{ID: "px-8a", Platform: driver.Android, Name: "Pixel 8a", Model: "Pixel 8a", OSVersion: "16",
		Connection: "usb", Backend: "scrcpy", State: driver.StateUnauthorized,
		Detail: "Unlock the phone and allow USB debugging for this computer."}
	iphone := driver.Info{ID: "00008140-0016", Platform: driver.IOS, Name: "iPhone 16", Model: "iPhone 16", OSVersion: "27.1",
		Connection: "usb", Backend: "coredevice", State: driver.StateUnauthorized, Setup: driver.SetupTrust,
		Detail: "Unlock the iPhone and tap Trust on the \"Trust This Computer?\" prompt, then enter its passcode."}
	droid.list(pixel)
	ios.list(iphone)
	ga := newStepsApp(t, droid, ios)
	is := func(id string, st gateway.DeviceStatus) bool { return ga.device(id).Status == st }
	ga.waitFor(t, "both phones", func() bool {
		return is(pixel.ID, gateway.DeviceNeedsSetup) && is(iphone.ID, gateway.DeviceNeedsSetup)
	})

	const w, h = 1280, 820
	for _, lang := range []string{"en", "zh-Hans"} {
		tt := mg.NewTester(ga.view, w, h)
		inLanguage(t, lang, tt)
		status := locales.GwStatusNeedsSetup()
		page := func(name string, want, not []string) {
			t.Helper()
			tt.Frame()
			tt.Frame()
			for _, s := range want {
				if !hasText(tt, s) {
					t.Errorf("%s: %s's page lacks %q: %q", lang, name, s, tt.Texts())
				}
			}
			for _, s := range not {
				if hasText(tt, s) {
					t.Errorf("%s: %s's page shows %q: %q", lang, name, s, tt.Texts())
				}
			}
			for _, d := range []driver.Info{pixel, iphone} {
				if _, ok := tt.Find(locales.SidebarPhoneRow(d.Name, status)); !ok {
					t.Errorf("%s: the sidebar does not say %s needs setup: %q", lang, d.Name, tt.Texts())
				}
			}
		}

		ga.chk.showing = ""
		ga.selectPhone(pixel.ID)
		page("Pixel 8a", []string{locales.PhoneNeedsSetup(pixel.Name), locales.CheckAuthorizedAndroidFail(), locales.PhoneCheckupFix()},
			[]string{locales.PhoneOffline(pixel.Name), locales.PhoneReconnect(), locales.PhoneSetUpIPhone(), pixel.Detail})
		ga.selectPhone(iphone.ID)
		page("iPhone 16", []string{locales.PhoneNeedsSetup(iphone.Name), locales.AddPhoneIPhoneStepTrustDetail(),
			locales.PhoneCheckupFix(), locales.PhoneSetUpIPhone()},
			[]string{locales.PhoneOffline(iphone.Name), locales.PhoneReconnect(), iphone.Detail})

		// All phones: both tiles say it, and neither counts as offline.
		ga.sel = allPhones
		tt.Frame()
		tiles := 0
		for _, s := range tt.Texts() {
			if s == status {
				tiles++
			}
		}
		if tiles < 4 || !hasText(tt, locales.PhoneConnected(2)) || hasText(tt, locales.PhoneOfflineCount(1)) {
			t.Errorf("%s: All phones shows %d × %q: %q", lang, tiles, status, tt.Texts())
		}

		// The menu bar flyout: a click on a phone shows its page.
		ft := mg.NewTester(ga.flyoutView, 320, ga.flyoutHeight())
		inLanguage(t, lang, ft)
		ft.Frame()
		for _, d := range []driver.Info{pixel, iphone} {
			if _, ok := ft.Find(locales.FlyoutPhoneLabel(d.Name, status)); !ok {
				t.Errorf("%s: the flyout does not say %s needs setup: %q", lang, d.Name, ft.Texts())
			}
		}
		if err := ft.Click(locales.FlyoutPhoneLabel(pixel.Name, status)); err != nil || ga.sel != pixel.ID || ga.page != pagePhones {
			t.Errorf("%s: the flyout's Pixel 8a: %v, showing %q on page %v", lang, err, ga.sel, ga.page)
		}
	}

	// See what's wrong: the checkup says the same step.
	tt := mg.NewTester(ga.view, w, h)
	ga.selectPhone(pixel.ID)
	tt.Frame()
	if err := tt.Click(locales.PhoneCheckupFix()); err != nil {
		t.Fatal(err)
	}
	ga.waitFor(t, "the checkup", func() bool { tt.Frame(); r := ga.checkupOf(pixel.ID); return r != nil && r.have && !r.running })
	tt.Frame()
	if ga.chk.showing != pixel.ID || !hasText(tt, locales.CheckAuthorizedAndroidFail()) {
		t.Errorf("the checkup of the Pixel: %q", tt.Texts())
	}
	ga.chk.showing = ""

	// Show the steps: Add phone › iPhone follows the iPhone.
	ga.selectPhone(iphone.ID)
	tt.Frame()
	if err := tt.Click(locales.PhoneSetUpIPhone()); err != nil || ga.page != pageAddPhone || ga.add.focus != iphone.ID {
		t.Errorf("Show the steps: %v, page %v, following %q", err, ga.page, ga.add.focus)
	}

	// The iPhone trusts the computer and waits for Developer Mode.
	iphone.State, iphone.Setup = driver.StateNeedsSetup, driver.SetupDeveloperMode
	iphone.Detail = "Turn on Developer Mode: on the iPhone, open Settings > Privacy & Security > Developer Mode, turn it on and tap Restart."
	ios.list(iphone)
	ga.waitFor(t, "Developer Mode", func() bool { return ga.device(iphone.ID).Info.Setup == driver.SetupDeveloperMode })
	ga.selectPhone(iphone.ID)
	tt.Frame()
	if !hasText(tt, locales.AddPhoneIPhoneStepDevModeDetail()) || hasText(tt, iphone.Detail) || hasText(tt, locales.AddPhoneIPhoneStepTrustDetail()) {
		t.Errorf("waiting for Developer Mode: %q", tt.Texts())
	}

	// Unplugged while they wait: offline, without the step.
	droid.list()
	ios.list()
	ga.waitFor(t, "both phones offline", func() bool {
		return is(pixel.ID, gateway.DeviceOffline) && is(iphone.ID, gateway.DeviceOffline)
	})
	tt.Frame()
	tt.Frame()
	if !hasText(tt, locales.PhoneOffline(iphone.Name)) || !hasText(tt, locales.PhoneNotConnected()) ||
		hasText(tt, locales.PhoneNeedsSetup(iphone.Name)) || hasText(tt, locales.AddPhoneIPhoneStepDevModeDetail()) {
		t.Errorf("the unplugged iPhone's page: %q", tt.Texts())
	}
	for _, d := range []driver.Info{pixel, iphone} {
		if _, ok := tt.Find(locales.SidebarPhoneRow(d.Name, locales.GwStatusOffline())); !ok || hasText(tt, locales.GwStatusNeedsSetup()) {
			t.Errorf("the sidebar for the unplugged %s: %q", d.Name, tt.Texts())
		}
	}
}

// TestIPhonePasscodeStep: while iOS asks for its passcode before the
// WebDriverAgent helper may control the iPhone, the phone's page, Add
// phone › iPhone and the checkup say so in the person's language, not in
// the driver's English, and not as a step Pinky could not finish.
func TestIPhonePasscodeStep(t *testing.T) {
	ta := newTestAppWith(t, fakeapi.Options{Scenario: fakeapi.OnePhone, Speed: 50, HoldSetup: true})
	ta.api.ConnectIPhone()
	ta.waitFor(t, "the iPhone", func() bool { return len(ta.devices) > 1 })
	id := ta.iphoneView(t).Info.ID
	const detail = "Enter the passcode on the iPhone: iOS asks for it now and then before the WebDriverAgent helper can control the phone."
	ta.api.SetIPhone(id, driver.Info{State: driver.StateNeedsSetup, Setup: driver.SetupPasscode, Detail: detail})
	ta.sync()
	for _, lang := range []string{"en", "zh-Hans"} {
		tt := mg.NewTester(ta.view, 1280, 820)
		inLanguage(t, lang, tt)
		want := locales.AddPhoneIPhoneStepPasscodeDetail()
		english := func(where string) {
			t.Helper()
			if lang != "en" && hasText(tt, detail) {
				t.Errorf("%s: %s shows the driver's English: %q", lang, where, tt.Texts())
			}
		}

		ta.chk.showing = ""
		ta.selectPhone(id)
		tt.Frame()
		tt.Frame()
		if !hasText(tt, locales.PhoneNeedsSetup(ta.iphoneView(t).Info.Name)) || !hasText(tt, want) {
			t.Errorf("%s: the phone's page: %q", lang, tt.Texts())
		}
		english("the phone's page")

		ta.openCheckup(ta.iphoneView(t))
		ta.frameUntil(t, tt, "the checkup", func() bool { r := ta.checkupOf(id); return r != nil && r.have && !r.running })
		if !hasText(tt, locales.AddPhoneIPhoneStepPasscode()) || !hasText(tt, want) {
			t.Errorf("%s: the checkup: %q", lang, tt.Texts())
		}
		english("the checkup")
		ta.chk.showing = ""

		ta.page = pageAddPhone
		ta.add.reset(ta.app)
		ta.add.step, ta.add.focus = "iphone", id
		tt.Frame()
		tt.Frame()
		if !hasText(tt, want) || hasText(tt, locales.AddPhoneIPhoneStuck()) || hasText(tt, locales.AddPhoneIPhoneRetrying()) {
			t.Errorf("%s: Add phone › iPhone: %q", lang, tt.Texts())
		}
		english("Add phone")
	}
}

// shows reports whether the frame has an element showing or labeled s
// exactly, such as a button.
func shows(tt *mg.Tester, s string) bool {
	_, ok := tt.Find(s)
	return ok
}

// TestAgentWaitsForSetupStep: on the real gateway, an agent connects to a
// phone that waits for a step and asks the person to do it. Its task card
// says the phone needs setup, without Take over; the handoff card says the
// agent goes on once the phone is ready, with Decline and Done but no Take
// over. Done before the step tells the agent the phone still waits.
func TestAgentWaitsForSetupStep(t *testing.T) {
	droid := &stepsProvider{platform: driver.Android}
	pixel := driver.Info{ID: "px-8a", Platform: driver.Android, Name: "Pixel 8a", Model: "Pixel 8a", OSVersion: "16",
		Connection: "usb", Backend: "scrcpy", State: driver.StateUnauthorized,
		Detail: "Unlock the phone and allow USB debugging for this computer."}
	droid.list(pixel)
	ga := newStepsApp(t, droid)
	ga.waitFor(t, "the phone", func() bool { return ga.device(pixel.ID).Status == gateway.DeviceNeedsSetup })
	ctx := context.Background()
	s := ga.w.Gateway.OpenSession(gateway.AgentInfo{Name: "Claude Code"})
	defer s.Close()
	if res := s.Connect(ctx, gateway.ConnectRequest{Call: gateway.Call{Device: pixel.ID}, Task: "Reorder lunch"}); res.Status != gateway.StatusNeedsSetup {
		t.Fatalf("connecting: %+v", res)
	}
	ga.waitFor(t, "the task", func() bool { return ga.taskOf(pixel.ID) != nil })
	ga.selectPhone(pixel.ID)
	for _, lang := range []string{"en", "zh-Hans"} {
		tt := mg.NewTester(ga.view, 1280, 820)
		inLanguage(t, lang, tt)
		tt.Frame()
		if !hasText(tt, locales.TasksStatusNeedsSetup()) || !hasText(tt, locales.TasksStop()) || shows(tt, locales.PhoneTakeOver()) ||
			hasText(tt, locales.TasksStatusWorking()) {
			t.Errorf("%s: the task card: %q", lang, tt.Texts())
		}
	}

	done := make(chan *gateway.Result, 1)
	go func() {
		done <- s.Handoff(ctx, gateway.HandoffRequest{Reason: "Allow USB debugging on the Pixel"})
	}()
	ga.waitFor(t, "the handoff", func() bool { return len(ga.needs) > 0 })
	var tt *mg.Tester
	for _, lang := range []string{"zh-Hans", "en"} {
		tt = mg.NewTester(ga.view, 1280, 820)
		inLanguage(t, lang, tt)
		tt.Frame()
		if !hasText(tt, locales.NeedsHandoffSetup("Claude Code")) || !shows(tt, locales.NeedsDecline()) || !shows(tt, locales.NeedsDone()) ||
			shows(tt, locales.PhoneTakeOver()) {
			t.Errorf("%s: the handoff card: %q", lang, tt.Texts())
		}
	}
	if err := tt.Click(locales.NeedsDone()); err != nil {
		t.Fatal(err)
	}
	ga.sync()
	select {
	case r := <-done:
		if r.Status != gateway.StatusNeedsSetup || !strings.Contains(r.Message, "still waits") {
			t.Errorf("Done before the step: %+v", r)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("Done did not answer the handoff")
	}
}

// TestIPhoneConnectionStep: an iPhone below iOS 27 set to connect through
// CoreDevice says, in the person's language, that it needs another
// connection, on its page, in its checkup and in Add phone, each with a
// way to Settings › Phones, where the connection is chosen; not the
// driver's English, the steps of Add phone, or a step Pinky retries.
func TestIPhoneConnectionStep(t *testing.T) {
	ta := newTestAppWith(t, fakeapi.Options{Scenario: fakeapi.OnePhone, Speed: 50, HoldSetup: true})
	ta.api.ConnectIPhone()
	ta.waitFor(t, "the iPhone", func() bool { return len(ta.devices) > 1 })
	id := ta.iphoneView(t).Info.ID
	const detail = "Connecting without the helper needs iOS 27 or later; this iPhone runs iOS 18.6. Choose Automatic or WebDriverAgent in Settings > Phones."
	ta.api.SetIPhone(id, driver.Info{State: driver.StateNeedsSetup, Setup: driver.SetupConnection, Detail: detail, OSVersion: "18.6"})
	ta.sync()
	for _, lang := range []string{"en", "zh-Hans"} {
		tt := mg.NewTester(ta.view, 1280, 820)
		inLanguage(t, lang, tt)
		want := locales.ConnectionChosenNeedsIOS27("18.6")
		check := func(where string, ok bool) {
			t.Helper()
			if !ok || hasText(tt, detail) {
				t.Errorf("%s: %s: %q", lang, where, tt.Texts())
			}
		}
		toSettings := func(where string) {
			t.Helper()
			if err := tt.Click(locales.ConnectionChoose()); err != nil || ta.page != pageSettings || ta.set.sec != secPhones {
				t.Errorf("%s: %s, Choose the connection: %v, page %v, section %v", lang, where, err, ta.page, ta.set.sec)
			}
		}

		ta.chk.showing = ""
		ta.selectPhone(id)
		tt.Frame()
		tt.Frame()
		check("the phone's page", hasText(tt, locales.PhoneNeedsSetup(ta.iphoneView(t).Info.Name)) && hasText(tt, want) &&
			!shows(tt, locales.PhoneSetUpIPhone()))
		toSettings("the phone's page")

		ta.openCheckup(ta.iphoneView(t))
		ta.frameUntil(t, tt, "the checkup", func() bool { r := ta.checkupOf(id); return r != nil && r.have && !r.running })
		check("the checkup", hasText(tt, locales.ConnectionTitle()) && hasText(tt, want))
		toSettings("the checkup")
		ta.chk.showing = ""

		ta.page = pageAddPhone
		ta.add.reset(ta.app)
		ta.add.step, ta.add.focus = "iphone", id
		tt.Frame()
		tt.Frame()
		check("Add phone › iPhone", hasText(tt, want) && !hasText(tt, locales.AddPhoneIPhoneStuck()) && !hasText(tt, locales.AddPhoneIPhoneRetrying()))
		toSettings("Add phone › iPhone")
	}
}

package update

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"

	"golang.org/x/sys/windows"
)

// The Windows parts of the helper that the fakes of helper_test.go stand in
// for, against the system: the installer's command line, how Pinky is
// started, versions and processes. The test binary plays the installer and
// Pinky (childEnv).

const childEnv = "PINKY_UPDATE_TEST_CHILD"

func TestMain(m *testing.M) {
	switch os.Getenv(childEnv) {
	case "":
		os.Exit(m.Run())
	case "record":
		// Writes its command line and how it was asked to show its
		// window, then exits with PINKY_UPDATE_TEST_EXIT.
		var si windows.StartupInfo
		windows.GetStartupInfo(&si)
		line := windows.UTF16PtrToString(windows.GetCommandLine())
		os.WriteFile(os.Getenv("PINKY_UPDATE_TEST_OUT"), []byte(fmt.Sprintf("%d %d\n%s", si.Flags, si.ShowWindow, line)), 0o600)
		code, _ := strconv.Atoi(os.Getenv("PINKY_UPDATE_TEST_EXIT"))
		os.Exit(code)
	case "sleep":
		time.Sleep(time.Minute)
		os.Exit(0)
	}
}

func recorded(t *testing.T, out string) (flags, show uint64, line string) {
	t.Helper()
	data, err := os.ReadFile(out)
	if err != nil {
		t.Fatal(err)
	}
	head, line, _ := strings.Cut(string(data), "\n")
	f, s, _ := strings.Cut(head, " ")
	flags, _ = strconv.ParseUint(f, 10, 32)
	show, _ = strconv.ParseUint(s, 10, 32)
	return flags, show, line
}

// TestRunSetup: the installer gets /S and /D= last and unquoted, even with
// spaces in the folder, and its exit code says how it went.
func TestRunSetup(t *testing.T) {
	out := filepath.Join(t.TempDir(), "out")
	dir := filepath.Join(t.TempDir(), "Program Files Here", "Pinky")
	t.Setenv(childEnv, "record")
	t.Setenv("PINKY_UPDATE_TEST_OUT", out)
	t.Setenv("PINKY_UPDATE_TEST_EXIT", "0")
	if err := runSetup(context.Background(), os.Args[0], dir); err != nil {
		t.Fatal(err)
	}
	if _, _, line := recorded(t, out); !strings.HasSuffix(line, " /S /D="+dir) {
		t.Errorf("the installer's command line: %s", line)
	}
	t.Setenv("PINKY_UPDATE_TEST_EXIT", "2")
	if err := runSetup(context.Background(), os.Args[0], dir); err == nil || err.Error() != "the installer exited with 2" {
		t.Errorf("an installer that exits with 2: %v", err)
	}
}

// TestStartPinky: the new version is started so that its window shows,
// and the helper hidden.
func TestStartPinky(t *testing.T) {
	out := filepath.Join(t.TempDir(), "out")
	p, err := startPinky(os.Args[0], []string{"--background"}, []string{childEnv + "=record", "PINKY_UPDATE_TEST_OUT=" + out, "PINKY_UPDATE_TEST_EXIT=0"})
	if err != nil {
		t.Fatal(err)
	}
	select {
	case <-p.Done():
	case <-time.After(30 * time.Second):
		t.Fatal("the started process did not exit")
	}
	flags, show, line := recorded(t, out)
	if flags&windows.STARTF_USESHOWWINDOW != 0 && show == windows.SW_HIDE {
		t.Error("Pinky was started hidden: its window would not show")
	}
	if !strings.HasSuffix(line, " --background") {
		t.Errorf("Pinky's command line: %s", line)
	}
}

func TestProcesses(t *testing.T) {
	p, err := startPinky(os.Args[0], nil, []string{childEnv + "=sleep"})
	if err != nil {
		t.Fatal(err)
	}
	pid := p.(*winProc).pid
	if processExited(pid, 100*time.Millisecond) {
		t.Fatal("a running process counts as exited")
	}
	w := watchProcess(pid)
	if err := w.Kill(); err != nil {
		t.Fatal(err)
	}
	select {
	case <-w.Done():
	case <-time.After(10 * time.Second):
		t.Fatal("the watched process did not end")
	}
	if !processExited(pid, 10*time.Second) {
		t.Error("an ended process does not count as exited")
	}
	select {
	case <-p.Done():
	case <-time.After(10 * time.Second):
		t.Error("the started process is not done")
	}
	if !processExited(1<<30, 0) {
		t.Error("no such process counts as running")
	}
	select {
	case <-watchProcess(1 << 30).Done():
	default:
		t.Error("watching no such process is not done")
	}
}

func TestFileVersion(t *testing.T) {
	v, err := fileVersion(filepath.Join(os.Getenv("SystemRoot"), "System32", "kernel32.dll"))
	if err != nil || !IsRelease(v) {
		t.Errorf("kernel32.dll's version: %q, %v", v, err)
	}
	if _, err := fileVersion(os.Args[0]); err == nil {
		t.Error("a program without a version resource has one")
	}
}

package update

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"
)

// These tests work on fake bundles in temporary folders; they never touch
// an installed Pinky.app or the running one.

// fakeBundle makes dir/name, a bundle of Pinky at version with a shell
// script for its executable.
func fakeBundle(t *testing.T, dir, name, id, version string) string {
	t.Helper()
	app := filepath.Join(dir, name)
	if err := os.MkdirAll(filepath.Join(app, "Contents", "MacOS"), 0o755); err != nil {
		t.Fatal(err)
	}
	plist := `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
<key>CFBundleIdentifier</key><string>` + id + `</string>
<key>CFBundleShortVersionString</key><string>` + version + `</string>
<key>CFBundleExecutable</key><string>Pinky</string>
</dict></plist>`
	if err := os.WriteFile(filepath.Join(app, "Contents", "Info.plist"), []byte(plist), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(app, "Contents", "MacOS", "Pinky"), []byte("#!/bin/sh\necho "+version+"\n"), 0o755); err != nil {
		t.Fatal(err)
	}
	return app
}

// zipBundle zips a bundle as the release does: ditto -c -k --keepParent.
func zipBundle(t *testing.T, app string) string {
	t.Helper()
	zip := filepath.Join(t.TempDir(), "Pinky.zip")
	if out, err := exec.Command("/usr/bin/ditto", "-c", "-k", "--keepParent", app, zip).CombinedOutput(); err != nil {
		t.Fatalf("ditto: %v: %s", err, out)
	}
	return zip
}

func acceptAll(context.Context, string) error { return nil }

func installedVersion(t *testing.T, app string) string {
	t.Helper()
	info, err := readBundleInfo(app)
	if err != nil {
		t.Fatal(err)
	}
	return info.Version
}

func TestStageChecksTheBundle(t *testing.T) {
	apps := t.TempDir()
	installed := fakeBundle(t, apps, "Pinky.app", BundleID, "2026.1107.1")
	src := t.TempDir()
	r := Release{Feed: Feed{Version: "2026.1107.2"}}

	good := zipBundle(t, fakeBundle(t, src, "Pinky.app", BundleID, "2026.1107.2"))
	in := &BundleInstaller{Bundle: installed, Verify: acceptAll}
	st, err := in.Stage(context.Background(), good, r)
	if err != nil {
		t.Fatal(err)
	}
	sb := st.(*stagedBundle)
	if !strings.HasPrefix(filepath.Base(sb.work), ".Pinky.app.update-") || filepath.Dir(sb.work) != apps {
		t.Errorf("staged in %s, not next to the app", sb.work)
	}
	if installedVersion(t, sb.app) != "2026.1107.2" {
		t.Errorf("the staged app")
	}
	st.Discard()
	if _, err := os.Stat(sb.work); !os.IsNotExist(err) {
		t.Errorf("Discard left %s", sb.work)
	}

	for _, c := range []struct {
		name, zip, want string
	}{
		{"another version", zipBundle(t, fakeBundle(t, t.TempDir(), "Pinky.app", BundleID, "2026.1107.1")), "version"},
		{"another app", zipBundle(t, fakeBundle(t, t.TempDir(), "Pinky.app", "com.example.other", "2026.1107.2")), "not Pinky"},
		{"not a zip", writeFile(t, "not a zip"), "unpack"},
	} {
		if _, err := in.Stage(context.Background(), c.zip, r); err == nil || !strings.Contains(err.Error(), c.want) {
			t.Errorf("%s: %v", c.name, err)
		}
	}
	two := t.TempDir()
	fakeBundle(t, two, "Pinky.app", BundleID, "2026.1107.2")
	fakeBundle(t, two, "Other.app", BundleID, "2026.1107.2")
	zip := filepath.Join(t.TempDir(), "two.zip")
	if out, err := exec.Command("/usr/bin/ditto", "-c", "-k", two, zip).CombinedOutput(); err != nil {
		t.Fatalf("ditto: %v: %s", err, out)
	}
	if _, err := in.Stage(context.Background(), zip, r); err == nil || !strings.Contains(err.Error(), "2 apps") {
		t.Errorf("two apps: %v", err)
	}
	leftovers, _ := filepath.Glob(filepath.Join(apps, ".Pinky.app.update-*"))
	if len(leftovers) != 0 {
		t.Errorf("failed stages left %v", leftovers)
	}

	// The real check refuses a bundle that Pinky's team did not sign.
	in.Verify = nil
	if _, err := in.Stage(context.Background(), good, r); !errors.Is(err, ErrSignature) {
		t.Errorf("an unsigned bundle: %v", err)
	}
}

func writeFile(t *testing.T, content string) string {
	t.Helper()
	p := filepath.Join(t.TempDir(), "file")
	if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	return p
}

// TestSignatureOfARelease checks the requirements against a Pinky.app signed
// with the Developer ID, when one is at hand: PINKY_SIGNED_APP, a release
// (notarized and stapled, as a release's zip holds it), else make release's
// build in the repository's build folder, which is not notarized. With
// PINKY_E2E_SIGN, the Developer ID itself, a changed copy signed again is
// Pinky's team's but not notarized, and must not pass as an update.
//
//	PINKY_SIGNED_APP=<unzipped release>/Pinky.app \
//	PINKY_E2E_SIGN="Developer ID Application: NATURAL SELECTION LABS PTE. LTD. (492J8Q67PF)" \
//	  go test -run TestSignatureOfARelease -v ./internal/update/
func TestSignatureOfARelease(t *testing.T) {
	ctx := context.Background()
	app := os.Getenv("PINKY_SIGNED_APP")
	release := app != ""
	if app == "" {
		app = filepath.Join("..", "..", "build", "pinky", "darwin-arm64", "Pinky.app")
	}
	if _, err := os.Stat(app); err != nil {
		t.Skip("no signed Pinky.app; set PINKY_SIGNED_APP")
	}
	out, _ := exec.Command("/usr/bin/codesign", "-dvv", app).CombinedOutput()
	if !strings.Contains(string(out), "TeamIdentifier="+TeamID) {
		t.Skipf("%s is not signed by Pinky's team", app)
	}
	if err := verifySignature(ctx, app, true); err != nil {
		t.Errorf("a release does not pass: %v", err)
	}
	if release && notarizationRequired {
		if err := verifyUpdate(ctx, app); err != nil {
			t.Errorf("a notarized release does not pass as an update: %v", err)
		}
	}
	// The same app copied and changed fails.
	cp := filepath.Join(t.TempDir(), "Pinky.app")
	if out, err := exec.Command("/usr/bin/ditto", app, cp).CombinedOutput(); err != nil {
		t.Fatalf("ditto: %v: %s", err, out)
	}
	if err := verifySignature(ctx, cp, true); err != nil {
		t.Errorf("an unchanged copy does not pass: %v", err)
	}
	if release && notarizationRequired {
		if err := verifyUpdate(ctx, cp); err != nil {
			t.Errorf("an unchanged copy of a release does not pass as an update: %v", err)
		}
	}
	os.WriteFile(filepath.Join(cp, "Contents", "Resources", "extra.txt"), []byte("added"), 0o644)
	if err := verifySignature(ctx, cp, true); !errors.Is(err, ErrSignature) {
		t.Errorf("a changed copy passes: %v", err)
	}

	// Signed again with Pinky's Developer ID, the changed copy is the
	// team's, but Apple never notarized it.
	sign := os.Getenv("PINKY_E2E_SIGN")
	if sign == "" || !notarizationRequired {
		return
	}
	os.Remove(filepath.Join(cp, "Contents", "CodeResources")) // the stapled ticket, of the release's code
	if out, err := exec.Command("/usr/bin/codesign", "--force", "--deep", "--timestamp=none", "--options", "runtime", "--sign", sign, cp).CombinedOutput(); err != nil {
		t.Fatalf("sign the changed copy: %v: %s", err, out)
	}
	if err := verifySignature(ctx, cp, true); err != nil {
		t.Errorf("the changed copy, signed again, is not the team's: %v", err)
	}
	if err := verifyUpdate(ctx, cp); !errors.Is(err, ErrNotarized) {
		t.Errorf("a copy that Apple did not notarize passes as an update: %v", err)
	}
	if out, err := codesign(ctx, cp, updateRequirement(), true); err == nil {
		t.Errorf("the helper's requirement accepts a copy that is not notarized: %s", out)
	}
}

// fakeApp is a process standing in for the running Pinky, which the helper
// waits for.
func fakeApp(t *testing.T) *exec.Cmd {
	t.Helper()
	cmd := exec.Command("/bin/sleep", "60")
	if err := cmd.Start(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { cmd.Process.Kill(); cmd.Wait() })
	return cmd
}

// fakeOpen stands in for /usr/bin/open: it records each start in starts
// and, as the new version would, runs CheckSwap's and Confirm's work for
// the version it finds at the bundle it is given. With crash set, the new
// version launches and exits before it is up.
func fakeOpen(t *testing.T, starts string, crash bool) []string {
	t.Helper()
	script := `app=$1; shift
v=$(sed -n 's:.*<key>CFBundleShortVersionString</key><string>\([^<]*\)</string>.*:\1:p' "$app/Contents/Info.plist")
echo "$v $*" >>` + strconv.Quote(starts) + `
for w in "$(dirname "$app")"/.Pinky.app.update-*; do
	[ -f "$w/pending.json" ] || continue
	grep -q "\"to\":\"$v\"" "$w/pending.json" || continue
	if [ "$CRASH" = 1 ]; then
		sh -c 'exit 0' & echo $! >"$w/launched"
	else
		echo $$ >"$w/launched"; : >"$w/started"
	fi
done
`
	env := "CRASH=0"
	if crash {
		env = "CRASH=1"
	}
	return []string{"/usr/bin/env", env, "/bin/sh", "-c", script, "fake-open"}
}

func waitUntil(t *testing.T, what string, d time.Duration, cond func() bool) {
	t.Helper()
	for deadline := time.Now().Add(d); time.Now().Before(deadline); time.Sleep(50 * time.Millisecond) {
		if cond() {
			return
		}
	}
	t.Fatalf("timed out waiting for %s", what)
}

func TestSwap(t *testing.T) {
	// A folder with spaces and quotes, as on an external disk.
	apps := filepath.Join(t.TempDir(), `My "Apps" $HOME`)
	if err := os.MkdirAll(apps, 0o755); err != nil {
		t.Fatal(err)
	}
	installed := fakeBundle(t, apps, "Pinky.app", BundleID, "2026.1107.1")
	os.WriteFile(filepath.Join(installed, "Contents", "old-only"), []byte("x"), 0o644)
	zip := zipBundle(t, fakeBundle(t, t.TempDir(), "Pinky.app", BundleID, "2026.1107.2"))
	running := fakeApp(t)
	starts := filepath.Join(t.TempDir(), "starts")
	log := filepath.Join(t.TempDir(), "update.log")
	in := &BundleInstaller{Bundle: installed, Verify: acceptAll, PID: running.Process.Pid, Open: fakeOpen(t, starts, false), Log: log}
	st, err := in.Stage(context.Background(), zip, Release{Feed: Feed{Version: "2026.1107.2"}})
	if err != nil {
		t.Fatal(err)
	}
	work := st.(*stagedBundle).work
	if err := st.Swap(StartOptions{Args: []string{"--background"}}); err != nil {
		t.Fatal(err)
	}
	// Nothing changes while the old version runs.
	time.Sleep(300 * time.Millisecond)
	if installedVersion(t, installed) != "2026.1107.1" {
		t.Fatal("swapped while Pinky still ran")
	}
	running.Process.Kill()
	running.Wait()
	waitUntil(t, "the swap", 10*time.Second, func() bool {
		_, err := os.Stat(work)
		return os.IsNotExist(err)
	})
	if v := installedVersion(t, installed); v != "2026.1107.2" {
		t.Errorf("installed %s", v)
	}
	if _, err := os.Stat(filepath.Join(installed, "Contents", "old-only")); !os.IsNotExist(err) {
		t.Error("the old bundle's files are in the new one")
	}
	data, _ := os.ReadFile(starts)
	if strings.TrimSpace(string(data)) != "2026.1107.2 --background" {
		t.Errorf("starts: %q", data)
	}
	logged, _ := os.ReadFile(log)
	if !strings.Contains(string(logged), "the new version is up") {
		t.Errorf("log:\n%s", logged)
	}
}

func TestSwapPutsTheOldVersionBack(t *testing.T) {
	apps := t.TempDir()
	installed := fakeBundle(t, apps, "Pinky.app", BundleID, "2026.1107.1")
	zip := zipBundle(t, fakeBundle(t, t.TempDir(), "Pinky.app", BundleID, "2026.1107.2"))
	running := fakeApp(t)
	starts := filepath.Join(t.TempDir(), "starts")
	log := filepath.Join(t.TempDir(), "update.log")
	in := &BundleInstaller{Bundle: installed, Verify: acceptAll, PID: running.Process.Pid, Open: fakeOpen(t, starts, true), Log: log}
	st, err := in.Stage(context.Background(), zip, Release{Feed: Feed{Version: "2026.1107.2"}})
	if err != nil {
		t.Fatal(err)
	}
	work := st.(*stagedBundle).work
	if err := st.Swap(StartOptions{}); err != nil {
		t.Fatal(err)
	}
	running.Process.Kill()
	running.Wait()
	waitUntil(t, "the old version to come back", 10*time.Second, func() bool {
		_, err := os.Stat(filepath.Join(work, "rolled-back"))
		return err == nil
	})
	waitUntil(t, "the old version to start again", 5*time.Second, func() bool {
		data, _ := os.ReadFile(starts)
		return strings.Count(string(data), "\n") == 2
	})
	if v := installedVersion(t, installed); v != "2026.1107.1" {
		t.Errorf("installed %s after a failed start", v)
	}
	data, _ := os.ReadFile(starts)
	if got := strings.Fields(string(data)); len(got) != 2 || got[0] != "2026.1107.2" || got[1] != "2026.1107.1" {
		t.Errorf("starts: %q", data)
	}
	// The old version, started again, learns that the update failed and
	// clears what is left.
	sw := checkSwap(installed, "2026.1107.1", os.Getpid(), time.Now())
	if sw == nil || !sw.Failed || sw.To != "2026.1107.2" || sw.From != "2026.1107.1" {
		t.Fatalf("checkSwap = %+v", sw)
	}
	if _, err := os.Stat(work); !os.IsNotExist(err) {
		t.Errorf("%s is left", work)
	}
	logged, _ := os.ReadFile(log)
	if !strings.Contains(string(logged), "did not start; putting the old one back") {
		t.Errorf("log:\n%s", logged)
	}
}

